for _, m in ipairs({ "gq_enums", "gq_types", "gq_state", "gq_util", "gq_defs", "gq_data", "gq_world", "gq_mobs", "gq_items",
	"gq_combat", "gq_ai", "gq_magic", "gq_quests", "gq_actions", "gq_sim", "gq_bot" }) do require(m) end

local every = 1000
for i = 1, #arg - 1 do
	if arg[i] == "every" then every = tonumber(arg[i + 1]) end
end

local excl, incl, names, samples = {}, {}, {}, 0
local getinfo = debug.getinfo
local function key_of(info)
	local k = info.short_src:match("[^/\\]*$") .. ":" .. info.linedefined
	if info.name and not names[k] then names[k] = info.name end
	return k
end
local function hook()
	samples = samples + 1
	local info = getinfo(2, "Sn")
	if not info then return end
	local k = key_of(info)
	excl[k] = (excl[k] or 0) + 1
	local seen = {}
	local level = 2
	while true do
		local fi = getinfo(level, "Sn")
		if not fi then break end
		if fi.what == "Lua" then
			local fk = key_of(fi)
			if not seen[fk] then
