	table.sort(rows, function(a, b) return (excl[a] or 0) > (excl[b] or 0) end)
	io.stderr:write(string.format("PROFILE %d samples, every %d instructions\n", samples, every))
	io.stderr:write(string.format("%-34s %-26s %8s %8s\n", "function", "where", "excl%", "incl%"))
